  "inlineSchema": "// ============================================================================\n// MobilJuragan · Prisma schema\n// Provider: postgresql  (rekomendasi roadmap — lihat docs/PLANNING_TECH_STACK_DAN_ROADMAP.md)\n//\n// Catatan jujur:\n//  - DB TIDAK dijalankan/di-migrate di scaffolding awal (tidak ada Docker/psql\n//    lokal di workspace). Schema di-commit sebagai sumber kebenaran awal.\n//  - Migration stamp akan dibuat ketika PostgreSQL tersedia (prisma migrate dev).\n//  - `quoted_amount` dibuat nullable: tarif belum boleh di-hardcode sebagai angka.\n//  - `vehicle_id` berasal dari 9 kendaraan resmi di docs/design-tokens.json\n//    (di-_gate_ saat seed, bukan di level constraint schema).\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\n// Prisma 7: connection handling dipindah ke prisma.config.ts (adapter @prisma/adapter-pg).\n// Blok datasource di sini hanya menegaskan provider untuk editor/typegen.\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/// Relasi yang relevan (sesuai roadmap §3):\n/// User ▸ Booking ▸ (Vehicle, BookingStatusHistory)\n/// User ▸ SupportTicket ▸ TicketMessage\n/// User ▸ OtpVerification\n/// AdminAction ▸ AuditLog\n\nenum UserRole {\n  CUSTOMER\n  STAFF\n  ADMIN\n}\n\nenum BookingStatus {\n  CREATED // booking diterima sistem, belum dikonfirmasi\n  PENDING_CONFIRMATION // menunggu konfirmasi admin\n  CONFIRMED // admin konfirmasi armada & tarif\n  REJECTED\n  CANCELLED\n  IN_PROGRESS // penyewaan berjalan\n  COMPLETED\n}\n\nenum BookingStatusActor {\n  CUSTOMER\n  STAFF\n  ADMIN\n  SYSTEM\n}\n\nenum RentalType {\n  // kategori sewa; detail jenis final menyusul konfirmasi team/tarif\n  WITH_DRIVER\n  WITHOUT_DRIVER\n}\n\nenum OperationalStatus {\n  AVAILABLE\n  BOOKED\n  MAINTENANCE\n  UNAVAILABLE\n}\n\nenum TariffStatus {\n  CONFIRMED\n  PENDING_TEAM_CONFIRMATION\n}\n\nenum TicketStatus {\n  OPEN\n  IN_PROGRESS\n  WAITING_CUSTOMER\n  RESOLVED\n  CLOSED\n}\n\nenum TicketCategory {\n  GENERAL\n  PAYMENT_CONFIRMATION\n  VEHICLE_ISSUE\n  CANCELLATION\n  COMPLAINT\n  OTHER\n}\n\nmodel User {\n  id          String   @id @default(uuid())\n  fullName    String\n  phoneNumber String   @unique\n  role        UserRole @default(CUSTOMER)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Optional credential khusus rol staff/admin (backend auth, bukan OTP customer).\n  passwordHash String?\n  isActive     Boolean @default(true)\n\n  bookings         Booking[]\n  tickets          SupportTicket[]\n  sentMessages     TicketMessage[]\n  otpVerifications OtpVerification[]\n  auditLogs        AuditLog[]\n\n  @@map(\"users\")\n}\n\nmodel Vehicle {\n  id                String            @id @default(uuid())\n  // key referensi ke 9 kendaraan resmi docs/design-tokens.json\n  externalId        String            @unique\n  name              String\n  licensePlate      String\n  brand             String?\n  model             String?\n  seatingCapacity   Int\n  transmission      String? // AUTOMATIC | MANUAL — isi final mengikuti dataset\n  category          String? // MENANGANI isi referensi fleet (towncar/pickup/man)\n  imageUrl          String?\n  operationalStatus OperationalStatus @default(AVAILABLE)\n  createdAt         DateTime          @default(now())\n  updatedAt         DateTime          @updatedAt\n\n  bookings Booking[]\n\n  @@index([operationalStatus])\n  @@index([externalId])\n  @@map(\"vehicles\")\n}\n\nmodel Booking {\n  id          String  @id @default(uuid())\n  bookingCode String  @unique\n  customerId  String\n  customer    User    @relation(fields: [customerId], references: [id])\n  vehicleId   String\n  vehicle     Vehicle @relation(fields: [vehicleId], references: [id])\n\n  startDateTime   DateTime\n  endDateTime     DateTime\n  rentalType      RentalType\n  pickupLocation  String?\n  customerRequest String?\n  numberGuests    Int?\n\n  tariffStatus TariffStatus @default(PENDING_TEAM_CONFIRMATION)\n  // Boleh null sampai tarif dikonfirmasi tim MobilJuragan.\n  quotedAmount Decimal?     @db.Decimal(12, 2)\n\n  status        BookingStatus          @default(CREATED)\n  statusHistory BookingStatusHistory[]\n  createdAt     DateTime               @default(now())\n  updatedAt     DateTime               @updatedAt\n\n  @@index([customerId])\n  @@index([vehicleId])\n  @@index([status])\n  @@index([startDateTime, endDateTime])\n  @@map(\"bookings\")\n}\n\n/// Riwayat tiap perubahan status booking (business rule minimum #5).\nmodel BookingStatusHistory {\n  id          String             @id @default(uuid())\n  bookingId   String\n  booking     Booking            @relation(fields: [bookingId], references: [id])\n  fromStatus  BookingStatus?\n  toStatus    BookingStatus\n  actor       BookingStatusActor\n  actorUserId String? // staff/admin/customer id saat ini\n  note        String? // catatan internal\n  changedAt   DateTime           @default(now())\n\n  @@index([bookingId])\n  @@map(\"booking_status_history\")\n}\n\n/// OTP customer authentication. HASH OTP saja; plaintext TIDAK disimpan (roadmap §3).\nmodel OtpVerification {\n  id           String    @id @default(uuid())\n  userId       String\n  user         User      @relation(fields: [userId], references: [id])\n  phoneNumber  String // nomor tujuan\n  otpHash      String // hanya hash (Argon2id saat backend auth diterapkan)\n  purpose      String // mis. \"CUSTOMER_LOGIN\" | \"BOOKING_CONFIRM\"\n  expiresAt    DateTime\n  attemptCount Int       @default(0)\n  consumedAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  @@index([userId, phoneNumber])\n  @@index([expiresAt])\n  @@map(\"otp_verifications\")\n}\n\nmodel SupportTicket {\n  id           String          @id @default(uuid())\n  ticketNumber String          @unique\n  customerId   String\n  customer     User            @relation(fields: [customerId], references: [id])\n  title        String\n  category     TicketCategory\n  description  String\n  status       TicketStatus    @default(OPEN)\n  messages     TicketMessage[]\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@index([customerId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketMessage {\n  id         String        @id @default(uuid())\n  ticketId   String\n  ticket     SupportTicket @relation(fields: [ticketId], references: [id])\n  senderId   String\n  sender     User          @relation(fields: [senderId], references: [id])\n  body       String\n  isCustomer Boolean // pembeda arah pesan (independen saat backend; lihat catatan)\n  sentAt     DateTime      @default(now())\n\n  @@index([ticketId])\n  @@map(\"ticket_messages\")\n}\n\n/// Audit trail aktivitas penting admin (untuk staff/admin role).\nmodel AuditLog {\n  id         String   @id @default(uuid())\n  actorId    String?\n  actor      User?    @relation(fields: [actorId], references: [id])\n  action     String // mis. \"BOOKING_STATUS_CHANGED\", \"ADMIN_LOGIN\"\n  entityType String\n  entityId   String?\n  metadata   Json?\n  createdAt  DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n",
